import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';
import { usePendingWishlistItem } from './usePendingWishlistItem';

// Mocked at the same module boundary useWishlistAuthDrawer.test.tsx already mocks
// (@salesforce/retail-react-app/app/utils/utils), for the same reason: a controllable vi.fn()
// per function rather than exercising real window.sessionStorage.
vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  getSessionJSONItem: vi.fn(() => undefined),
  setSessionJSONItem: vi.fn(),
  clearSessionJSONItem: vi.fn(),
}));

const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);
const mockSetSessionJSONItem = vi.mocked(setSessionJSONItem);
const mockClearSessionJSONItem = vi.mocked(clearSessionJSONItem);

const PRODUCT_ID = 'product-abc';
const OTHER_PRODUCT_ID = 'product-xyz';
const TEN_MINUTES_MS = 10 * 60 * 1000; // well past the 5-minute bound this hook enforces

describe('usePendingWishlistItem', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGetSessionJSONItem.mockReturnValue(undefined);
  });

  test('a guest is never resumed — onResume is never called while isGuest stays true', () => {
    const onResume = vi.fn();
    const { result, rerender } = renderHook(
      ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
      {
        initialProps: { isGuest: true },
      },
    );

    act(() => result.current.beginPendingMove());
    rerender({ isGuest: true });

    expect(onResume).not.toHaveBeenCalled();
  });

  test('beginPendingMove persists the intent to session storage, keyed by productId', () => {
    const onResume = vi.fn();
    const { result } = renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: true, onResume }));

    act(() => result.current.beginPendingMove());

    expect(mockSetSessionJSONItem).toHaveBeenCalledTimes(1);
    const [key, value] = mockSetSessionJSONItem.mock.calls[0];
    expect(key).toBe('zimmPendingWishlistCartItem');
    expect(value).toMatchObject({ productId: PRODUCT_ID });
  });

  describe('resume from React state (email-code / create-account auth — the same instance stays mounted)', () => {
    test('a fresh pending item resumes once isGuest flips to false, and both stores are cleared', () => {
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      expect(onResume).not.toHaveBeenCalled();

      rerender({ isGuest: false });

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistCartItem');
    });

    test('with no pending item at all, isGuest flipping to false calls neither onResume nor clearSessionJSONItem', () => {
      const onResume = vi.fn();
      const { rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      rerender({ isGuest: false });

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('resume from session storage (Apple/Google redirect — a fresh mount, no prior React state)', () => {
    test('a fresh mount with isGuest already false and a matching stored intent resumes immediately', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).toHaveBeenCalledTimes(1);
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistCartItem');
    });

    test('a stored intent for a DIFFERENT product is left untouched — not resumed, not cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: OTHER_PRODUCT_ID, timestamp: Date.now() });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).not.toHaveBeenCalled();
    });
  });

  describe('a pending item older than 5 minutes (pass criterion 10)', () => {
    test('from session storage: not resumed, but both stores are still cleared', () => {
      mockGetSessionJSONItem.mockReturnValue({ productId: PRODUCT_ID, timestamp: Date.now() - TEN_MINUTES_MS });
      const onResume = vi.fn();

      renderHook(() => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest: false, onResume }));

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistCartItem');
    });

    test('from React state: not resumed once isGuest flips false, but both stores are still cleared', () => {
      // Mutation check on the fixture itself: a fresh (non-stale) timestamp on the exact same
      // path DOES resume (proved by the "resume from React state" describe block above), so this
      // failing when the timestamp is swapped for a stale one is a real assertion, not vacuous.
      const onResume = vi.fn();
      const { result, rerender } = renderHook(
        ({ isGuest }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
        {
          initialProps: { isGuest: true },
        },
      );

      act(() => result.current.beginPendingMove());
      // Directly age the in-memory intent's clock reference by controlling Date.now() at the
      // moment the resume effect actually checks freshness, rather than re-implementing
      // beginPendingMove with a hand-set timestamp.
      const dateNowSpy = vi.spyOn(Date, 'now').mockReturnValue(Date.now() + TEN_MINUTES_MS);
      rerender({ isGuest: false });
      dateNowSpy.mockRestore();

      expect(onResume).not.toHaveBeenCalled();
      expect(mockClearSessionJSONItem).toHaveBeenCalledWith('zimmPendingWishlistCartItem');
    });
  });
});

