import { defineMessages, useIntl } from 'react-intl';
import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';

/**
 * `@salesforce/retail-react-app` ships no TypeScript types (AGENTS.md's "Commerce SDK types not
 * importable" gotcha) — `use-toast.js` falls through `overrides/app/types/vendor.d.ts`'s catch-all
 * `declare module '@salesforce/retail-react-app/*'` (a shorthand ambient module declaration that
 * types the whole module `any` — see that file's own comment, and
 * `overrides/app/utils/recentlyViewedFullHistoryCard.ts`'s identical narrow-local-type pattern for
 * another untyped base function), so the real `useToast()` return value is implicitly `any`.
 * Declared narrow here, covering only the two fields this file actually sends (`title`, `status`)
 * rather than the base hook's full options surface (`description`, `action`, `position`,
 * `duration`, `variant`, `isClosable`) — nothing in this file uses those, so typing them would be
 * speculative. `status`'s four values are copied verbatim from the base hook's real accepted set
 * (not narrowed to only `'success' | 'warning'`), so a later message that genuinely needs `'error'`
 * or `'info'` — SFCC-404's rework, or any message added after this step — is already covered
 * without a signature change here.
 *
 * This is a type annotation documenting an assumed shape, not a runtime guarantee — TypeScript
 * allows asserting `any` to any narrower type with no check. The real proof is this file's own
 * test, which asserts the exact object the mocked toast function is called with.
 */
type CartToastStatus = 'success' | 'error' | 'info' | 'warning';
type CartToastFn = (options: { title: string; status: CartToastStatus }) => void;

/**
 * The three real cart messages this step ships, copy verbatim from Figma (SFCC-11 plan step 4.3)
 * — this file never derives or paraphrases copy, only interpolates a product name into the one
 * message that needs it. SFCC-272's own AC text describes a generic stacked wording ("Item added
 * to Wishlist") for when more than one item has been added — deliberately not built here: a toast
 * has no aggregation concept, so that copy is only reachable once SFCC-404 ships real message
 * stacking. Until then every add uses this product-named variant, one toast per add.
 *
 * Wrapped in `defineMessages` (fixed 2026-09-20 — the original version of this file hardcoded
 * plain strings, the only visible cart copy in this build that did) so these three strings are
 * discoverable by whatever tooling extracts copy for this storefront's 11 locales the same way
 * `zimmQuantityStepper`'s own `messages` object already is. `defaultMessage` uses ICU
 * MessageFormat's `{productName}` placeholder syntax for the one message that interpolates.
 */
const messages = defineMessages({
  addedToWishlist: {
    id: 'use_cart_messages.added_to_wishlist',
    defaultMessage: '{productName} added to Wishlist',
  },
  alreadyInWishlist: {
    id: 'use_cart_messages.already_in_wishlist',
    defaultMessage: 'An item in your bag already exists in Wishlist',
  },
  maxQuantityReached: {
    id: 'use_cart_messages.max_quantity_reached',
    defaultMessage: 'An item in your bag has reached maximum quantity',
  },
});

export type UseCartMessagesReturn = {
  /**
   * SFCC-272 AC5 — a single product was moved from the cart to the wishlist. `productName` is
   * interpolated into the copy on every call — never hardcode a specific product's name at a call
   * site. `success` status.
   */
  notifyAddedToWishlist: (productName: string) => void;
  /**
   * SFCC-272 AC6 — the item already exists in the shopper's wishlist; the caller leaves the cart
   * line untouched. Verbatim copy, no interpolation. `warning` status — see
   * `notifyMaxQuantityReached`'s own doc for why cart feedback that doesn't block anything reads
   * as a warning in this build, not an error.
   */
  notifyAlreadyInWishlist: () => void;
  /**
   * CAI-017 / SFCC-250 — a cart line has reached its maximum orderable quantity (the line is
   * already capped by `useCartMergeAndCap` before this ever fires). `warning`, not `error`:
   * CAI-017's own requirement text says "an error message will be displayed", but the Figma
   * rendering uses the warning variant and SFCC-250 AC4 confirms this never blocks checkout — this
   * build's own gate resolved the wording as meaning user-facing feedback, not literally Chakra's
   * error severity (the same reconciliation `ZimmInlineMessage`'s own `variant` prop documents —
   * `overrides/app/components/ui-kits/atoms/zimmInlineMessage/index.tsx`: "a caller may
   * legitimately pass `variant=\"warning\"` for copy whose own requirement text uses the word
   * `error`").
   */
  notifyMaxQuantityReached: () => void;
};

/**
 * Hook — the one surface every cart toast message (success and warning today; whatever SFCC-404's
 * real stacking/aggregation rework needs later, including a genuine error) is sent through.
 * `emitCartMessage` below is the single call to the underlying toast function — a future rework
 * swaps what happens inside this one file, not a hunt across the cart UI for every place that
 * fires a toast.
 *
 * Wraps the **base** `useToast` (`@salesforce/retail-react-app/app/hooks/use-toast`) rather than a
 * new `overrides/app/hooks/use-toast.ts` — that path does not exist, and creating it would be an
 * unbudgeted Tier 2 change (`protectedFiles.md` would route it to both squads plus tier-2/tier-1
 * approvers). See the SFCC-11 plan's own resolved open question 4. This hook is the real "one
 * handler" the plan asks for; the base hook underneath it is just the interim renderer SFCC-404
 * replaces.
 *
 * @returns the three named cart-message senders callers actually invoke today. `emitCartMessage`
 * itself is intentionally not returned — nothing outside this file needs to send an
 * uncatalogued/arbitrary message yet, and a future message is one new named function here, not a
 * reason to widen this hook's public surface.
 */
export const useCartMessages = (): UseCartMessagesReturn => {
  // Real return type is implicit `any` (see CartToastFn's own docblock above) — asserted to the
  // local narrow type rather than left as `any`, so every call below is checked against the shape
  // this file actually depends on.
  const toast = useToast() as CartToastFn;
  const intl = useIntl();

  const emitCartMessage = (title: string, status: CartToastStatus): void => {
    // SFCC-404: this is the one real call to the underlying toast function. When SFCC-404's real
    // stacking/aggregation rework lands, this is the only line that changes.
    toast({ title, status });
  };

  return {
    notifyAddedToWishlist: (productName: string) =>
      emitCartMessage(intl.formatMessage(messages.addedToWishlist, { productName }), 'success'),
    notifyAlreadyInWishlist: () => emitCartMessage(intl.formatMessage(messages.alreadyInWishlist), 'warning'),
    notifyMaxQuantityReached: () => emitCartMessage(intl.formatMessage(messages.maxQuantityReached), 'warning'),
  };
};

