import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';
import { usePendingWishlistItem } from './usePendingWishlistItem';

vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  getSessionJSONItem: vi.fn(() => undefined),
  setSessionJSONItem: vi.fn(),
  clearSessionJSONItem: vi.fn(),
}));

const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);

const PRODUCT_ID = 'product-abc';

describe('SCRATCH TASK 1 — effect dep array: latest onResume is invoked, not a stale one', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGetSessionJSONItem.mockReturnValue(undefined);
  });

  test('onResume changes while isGuest stays true (no fire); then isGuest flips false — the LATEST onResume fires, not the stale one', () => {
    const onResumeV1 = vi.fn();
    const onResumeV2 = vi.fn();

    const { result, rerender } = renderHook(
      ({ isGuest, onResume }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
      { initialProps: { isGuest: true, onResume: onResumeV1 } },
    );

    act(() => result.current.beginPendingMove());

    // Rerender with a NEW onResume reference while isGuest stays true — deps array is [isGuest]
    // only, so this should NOT cause the effect to re-run at all.
    rerender({ isGuest: true, onResume: onResumeV2 });

    expect(onResumeV1).not.toHaveBeenCalled();
    expect(onResumeV2).not.toHaveBeenCalled();

    // Now flip isGuest to false in the SAME rerender call that still carries onResumeV2 — this is
    // the dep-array-triggering change. React must invoke the effect closure created on THIS render,
    // which closes over onResumeV2 (the latest), not onResumeV1 (the stale one from mount).
    rerender({ isGuest: false, onResume: onResumeV2 });

    expect(onResumeV1).not.toHaveBeenCalled();
    expect(onResumeV2).toHaveBeenCalledTimes(1);
  });

  test('onResume changes AGAIN on the very render where isGuest flips false — that same render latest onResume fires', () => {
    const onResumeV1 = vi.fn();
    const onResumeV2 = vi.fn();

    const { result, rerender } = renderHook(
      ({ isGuest, onResume }) => usePendingWishlistItem({ productId: PRODUCT_ID, isGuest, onResume }),
      { initialProps: { isGuest: true, onResume: onResumeV1 } },
    );

    act(() => result.current.beginPendingMove());

    // isGuest flips to false AND onResume changes to v2 in the same render — this is the render
    // whose closure must run, and it must run with v2.
    rerender({ isGuest: false, onResume: onResumeV2 });

    expect(onResumeV1).not.toHaveBeenCalled();
    expect(onResumeV2).toHaveBeenCalledTimes(1);
  });
});

