import { describe, test, expect, vi, beforeEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import {
  getSessionJSONItem,
  setSessionJSONItem,
  clearSessionJSONItem,
} from '@salesforce/retail-react-app/app/utils/utils';
import { usePendingWishlistItem } from './usePendingWishlistItem';

// A REAL shared in-memory backing store — standing in for actual browser sessionStorage, which
// genuinely is one shared key/value space across every hook instance on the page. Both mocked
// functions read/write this SAME object, unlike the existing suite's independent per-test
// `mockReturnValue` stubbing — that's the whole point: the real bug needs storage to reflect
// only whichever beginPendingMove call happened last, across two DIFFERENT hook instances.
let store: Record<string, unknown>;

vi.mock('@salesforce/retail-react-app/app/utils/utils', () => ({
  getSessionJSONItem: vi.fn(),
  setSessionJSONItem: vi.fn(),
  clearSessionJSONItem: vi.fn(),
}));

const mockGetSessionJSONItem = vi.mocked(getSessionJSONItem);
const mockSetSessionJSONItem = vi.mocked(setSessionJSONItem);
const mockClearSessionJSONItem = vi.mocked(clearSessionJSONItem);

const KEY = 'zimmPendingWishlistCartItem';

describe('SCRATCH TASK 3 — two cart rows sharing one sessionStorage key, then a full page reload', () => {
  beforeEach(() => {
    store = {};
    mockGetSessionJSONItem.mockImplementation((key: string) => store[key]);
    mockSetSessionJSONItem.mockImplementation((key: string, value: unknown) => {
      store[key] = value;
    });
    mockClearSessionJSONItem.mockImplementation((key: string) => {
      delete store[key];
    });
  });

  test('row A intent is silently lost when row B overwrites the shared key before a reload', () => {
    const onResumeA1 = vi.fn(); // row A's pre-reload hook instance
    const onResumeB1 = vi.fn(); // row B's pre-reload hook instance

    // Step 1 — guest clicks "Move to Wishlist" on row A.
    const rowA = renderHook(() =>
      usePendingWishlistItem({ productId: 'A', isGuest: true, onResume: onResumeA1 }),
    );
    act(() => rowA.result.current.beginPendingMove());

    expect(store[KEY]).toMatchObject({ productId: 'A' });

    // Step 2 — same session, guest clicks "Move to Wishlist" on row B. Row B's own hook instance
    // is independent local React state, but writes to the SAME shared storage key.
    const rowB = renderHook(() =>
      usePendingWishlistItem({ productId: 'B', isGuest: true, onResume: onResumeB1 }),
    );
    act(() => rowB.result.current.beginPendingMove());

    // The shared slot now holds ONLY row B's intent — row A's has been overwritten.
    expect(store[KEY]).toMatchObject({ productId: 'B' });

    // Step 3 — simulate a full page reload (e.g. Apple/Google redirect): ALL React state for
    // BOTH instances is destroyed. Model this with brand-new renderHook() mounts (not rerenders
    // of rowA/rowB above) — isGuest: false from each one's very first render, exactly like a
    // fresh page load post-auth. Both read from the SAME `store` backing object.
    const onResumeA2 = vi.fn(); // row A's fresh post-reload hook instance
    const onResumeB2 = vi.fn(); // row B's fresh post-reload hook instance

    renderHook(() => usePendingWishlistItem({ productId: 'A', isGuest: false, onResume: onResumeA2 }));
    renderHook(() => usePendingWishlistItem({ productId: 'B', isGuest: false, onResume: onResumeB2 }));

    // THE HYPOTHESIS: row A's guest intent is permanently, silently lost — its fresh post-reload
    // instance has no local `pending` state (destroyed by the reload) AND finds someone else's
    // (B's) data in the one shared slot, which does not match its own productId, so it treats it
    // as "nothing pending for me" and does nothing. No error, no retry, no signal to the shopper.
    expect(onResumeA2).not.toHaveBeenCalled();

    // Row B's own intent, being the one left in the shared slot, resumes normally — its own
    // matching product id is found in storage and it fires exactly once.
    expect(onResumeB2).toHaveBeenCalledTimes(1);

    // Confirm the pre-reload instances' onResume (from before the reload wiped state) were never
    // called either — nothing here is asserting a false negative from the wrong instance.
    expect(onResumeA1).not.toHaveBeenCalled();
    expect(onResumeB1).not.toHaveBeenCalled();
  });

  test('reversed mount order after reload (B before A) — same outcome, not order-dependent', () => {
    const onResumeA1 = vi.fn();
    const onResumeB1 = vi.fn();

    const rowA = renderHook(() =>
      usePendingWishlistItem({ productId: 'A', isGuest: true, onResume: onResumeA1 }),
    );
    act(() => rowA.result.current.beginPendingMove());

    const rowB = renderHook(() =>
      usePendingWishlistItem({ productId: 'B', isGuest: true, onResume: onResumeB1 }),
    );
    act(() => rowB.result.current.beginPendingMove());

    const onResumeA2 = vi.fn();
    const onResumeB2 = vi.fn();

    // Mount B's fresh post-reload instance FIRST this time.
    renderHook(() => usePendingWishlistItem({ productId: 'B', isGuest: false, onResume: onResumeB2 }));
    renderHook(() => usePendingWishlistItem({ productId: 'A', isGuest: false, onResume: onResumeA2 }));

    expect(onResumeA2).not.toHaveBeenCalled();
    expect(onResumeB2).toHaveBeenCalledTimes(1);
  });
});

